import React, { useState, useEffect } from 'react';
import Layout from '@/shared/ui/Layout/Layout';
import MatchCard from '@/shared/ui/MatchCard/MatchCard';
import { getLiveMatches } from '@/entities/match/api';
import { Match } from '@/entities/match/types';
import '../shared/ui/styles/LivePage.css';

const LivePage = () => {
  const [matches, setMatches] = useState<Match[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const data = await getLiveMatches();
        setMatches(data);
      } catch (err) {
        console.error('Ошибка получения live матчей:', err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();

    // Обновляем данные каждую минуту
    const interval = setInterval(fetchData, 60000);
    return () => clearInterval(interval);
  }, []);

  return (
    <Layout>
      <div className="container">
        <div className="page-header">
          <h1 className="page-title">
            <span className="live-dot"></span> 
            Матчи в прямом эфире
          </h1>
          <p className="page-description">
            Следите за актуальным ходом футбольных матчей
          </p>
        </div>

        {isLoading ? (
          <div className="loader-container">Загрузка...</div>
        ) : matches.length > 0 ? (
          <div className="live-matches">
            {matches.map((match, idx) => (
              <MatchCard
                key={idx}
                homeTeam={match.home}
                awayTeam={match.away}
                status="LIVE"
                date={match.date}
              />
            ))}
          </div>
        ) : (
          <div className="no-matches">
            <div className="no-matches-content">
              <h3>Нет прямых трансляций</h3>
              <p>В данный момент нет матчей в прямом эфире. Проверьте расписание предстоящих матчей.</p>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default LivePage;
